ALTER TABLE `Shop` ADD COLUMN `district` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `workingHours` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `description` VARCHAR(191) NOT NULL DEFAULT '';
ALTER TABLE `ShopApplication` ADD COLUMN `contactName` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `email` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `whatsapp` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `district` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `workingHours` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `description` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `registrationNumber` VARCHAR(191) NOT NULL DEFAULT '', ADD COLUMN `taxNumber` VARCHAR(191) NOT NULL DEFAULT '';
CREATE TABLE `ShopPhoto` (`id` VARCHAR(191) NOT NULL,`applicationId` VARCHAR(191) NULL,`shopId` VARCHAR(191) NULL,`role` VARCHAR(191) NOT NULL DEFAULT 'GALLERY',`url` VARCHAR(191) NOT NULL,`demo` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `ShopPhoto_applicationId_idx`(`applicationId`),INDEX `ShopPhoto_shopId_idx`(`shopId`),PRIMARY KEY(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ShopDocument` (`id` VARCHAR(191) NOT NULL,`applicationId` VARCHAR(191) NOT NULL,`kind` VARCHAR(191) NOT NULL,`file` VARCHAR(191) NOT NULL,`originalName` VARCHAR(191) NOT NULL,`mime` VARCHAR(191) NOT NULL,`size` INTEGER NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `ShopDocument_applicationId_idx`(`applicationId`),PRIMARY KEY(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
